# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.38.0/ankra-cli-darwin-arm64"
      sha256 "6cb51161df75ac135ff02dcdfc080a66584b1d2bf3dea64c654efaf510322c64"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.38.0/ankra-cli-darwin-amd64"
      sha256 "b221c8c4a952ce726d8f0283493a0c5baded4f67a6a9ab36eb8255680980b125"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.38.0/ankra-cli-linux-arm64"
      sha256 "f0f664f7dc8aa423ba11eb75e853f25b0496d50e3dc2b6aacec81c254e3f4691"
    end
    on_intel do
